const CORE = ["./", "./index.html", "./manifest.webmanifest", "./icon-180.png", "./icon-192.png", "./icon-512.png"];
// Polices (adresses à empreinte) : l'alphabet latin est gardé dès l'installation ; les variantes « latin-ext », rares,
// au premier usage. Toutes restent dans leur cache d'une version à l'autre.
const POLICES_CACHE = "archipel2-polices";
const POLICES = ["./polices/andika-latin-400-normal.woff2?v=dd6bb7266c","./polices/andika-latin-700-normal.woff2?v=61c90acb5f","./polices/baloo-2-latin-600-normal.woff2?v=ffc22b431d","./polices/baloo-2-latin-700-normal.woff2?v=8e7ffc9b99","./polices/baloo-2-latin-800-normal.woff2?v=3e36c57e37","./polices/inter-latin-400-normal.woff2?v=8909904ab6","./polices/inter-latin-600-normal.woff2?v=f9a06e79cd","./polices/inter-latin-700-normal.woff2?v=6f56409fd3"];
const POLICES_TOUTES = ["./polices/andika-latin-400-normal.woff2?v=dd6bb7266c","./polices/andika-latin-700-normal.woff2?v=61c90acb5f","./polices/andika-latin-ext-400-normal.woff2?v=3b5fd6ac2e","./polices/andika-latin-ext-700-normal.woff2?v=60bde176a3","./polices/baloo-2-latin-600-normal.woff2?v=ffc22b431d","./polices/baloo-2-latin-700-normal.woff2?v=8e7ffc9b99","./polices/baloo-2-latin-800-normal.woff2?v=3e36c57e37","./polices/baloo-2-latin-ext-600-normal.woff2?v=1a41005685","./polices/baloo-2-latin-ext-700-normal.woff2?v=c813752d17","./polices/baloo-2-latin-ext-800-normal.woff2?v=d73eb61f07","./polices/inter-latin-400-normal.woff2?v=8909904ab6","./polices/inter-latin-600-normal.woff2?v=f9a06e79cd","./polices/inter-latin-700-normal.woff2?v=6f56409fd3","./polices/inter-latin-ext-400-normal.woff2?v=6744a7f509","./polices/inter-latin-ext-600-normal.woff2?v=e4bdf67b0c","./polices/inter-latin-ext-700-normal.woff2?v=143f9504f1"];
const VOIX_FILES = ["./voix/atelier-2cb7735a18.mp3","./voix/coeur-8150be0fcc.mp3","./voix/commun-1e9755c09e.mp3","./voix/decouvertes-9307250f3b.mp3","./voix/enigmes-aead6d0575.mp3","./voix/index-c4d845fd8e.json","./voix/mots-59804273f6.mp3","./voix/nombres-d22c37b0f3.mp3","./voix/port-01579326cb.mp3"];

// Garde les fichiers qui manquent, six à la fois.
const keepAll = async (name, files) => {
  const cache = await caches.open(name);
  const missing = [];
  for (const f of files) if (!(await cache.match(f))) missing.push(f);
  for (let i = 0; i < missing.length; i += 6) {
    await Promise.all(missing.slice(i, i + 6).map(async (f) => {
      const response = await fetch(f);
      if (response.ok) await cache.put(f, response);
    }));
  }
};
const keepVoice = () => keepAll(VOIX, VOIX_FILES);
const keepImages = () => keepAll(IMAGES, IMAGES_FILES);

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(CORE))
      .then(() => keepAll(POLICES_CACHE, POLICES))
      .then(() => keepVoice().catch(() => { /* la voix sera gardée au fil des écoutes */ }))
      .then(() => keepImages().catch(() => { /* les images seront gardées au fil de l'affichage */ }))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  const wanted = new Set([...VOIX_FILES, ...IMAGES_FILES, ...POLICES_TOUTES].map((f) => new URL(f, self.location).href));
  const prune = (name) => caches.open(name).then((cache) => cache.keys().then((reqs) => Promise.all(reqs.filter((r) => !wanted.has(r.url)).map((r) => cache.delete(r)))));
  const kept = new Set([CACHE, VOIX, IMAGES, POLICES_CACHE]);
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("archipel2-") && !kept.has(k)).map((k) => caches.delete(k))))
      .then(() => Promise.all([prune(VOIX), prune(IMAGES), prune(POLICES_CACHE)]))
      .then(() => self.clients.claim()),
  );
});

const keep = (request, response) => {
  const copy = response.clone();
  caches.open(CACHE).then((cache) => cache.put(request, copy));
  return response;
};

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin === self.location.origin) {
    // Voix, images et polices : fichiers qui ne changent jamais (leur adresse change avec leur contenu) → copie gardée d'abord.
    const fixe = url.pathname.includes("/voix/") ? VOIX
      : url.pathname.includes("/illustrations/") || url.pathname.includes("/imagier/") ? IMAGES
      : url.pathname.includes("/polices/") ? POLICES_CACHE : null;
    if (fixe) {
      event.respondWith(caches.open(fixe).then((cache) => cache.match(request).then((hit) => hit || fetch(request).then((response) => {
        if (response.ok) cache.put(request, response.clone());
        return response;
      }))));
      return;
    }
    event.respondWith(
      fetch(request)
        .then((response) => (response.ok ? keep(request, response) : response))
        .catch(() => caches.match(request, { ignoreSearch: true }).then((hit) => hit || caches.match("./index.html"))),
    );
  }
});
